//! 🎟️ Original paged reservation currencies are admitted before any scalar-index backing mutation.
use super::*;
#[test]fn neutral_structural_reservations_match_ordered_reference(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for items in [1,7,4096]{let mut index=NumericIndex::<usize,usize>::new();let page_items=fixture["pageItems"].as_u64().unwrap()as usize;index.nodes=PagedList::with_payload_page_bytes(std::mem::size_of::<Node<usize,usize>>()*page_items).unwrap();let mut reference=std::collections::BTreeMap::new();let mut depths=std::collections::BTreeSet::new();for key in 0..fixture["keys"].as_u64().unwrap()as usize{while !index.nodes.has_reserved_slot(){let d=index.next_reserve_demand().unwrap();let grant=crate::RetainedCloneGrant{maximum_items:items,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:0,maximum_depth:d.depth};depths.insert(d.depth);for partial in [crate::RetainedCloneGrant{maximum_items:0,..grant},crate::RetainedCloneGrant{maximum_depth:d.depth-1,..grant},crate::RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..grant}]{let before=index.nodes.allocated_bytes();let p=index.reserve_one_funded(partial).unwrap();assert_eq!(p.retained_capacity_bytes,0);assert_eq!(p.copied_bytes,0);assert_eq!(index.nodes.allocated_bytes(),before);}if d.copy_bytes>0{assert_eq!(index.reserve_one_funded(crate::RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..grant}).unwrap().copied_bytes,0);}let p=index.reserve_one_funded(grant).unwrap();assert_eq!(p.retained_capacity_bytes,d.capacity_bytes);assert_eq!(p.copied_bytes,d.copy_bytes);assert_eq!(p.copied_items,1);}if key==0{assert_eq!(index.nodes.capacity(),page_items);}let value=key*fixture["multiplier"].as_u64().unwrap()as usize;assert!(index.insert_reserved(key,value).unwrap().is_none());reference.insert(key,value);}assert_eq!(depths.first().copied(),fixture["minimumDepth"].as_u64().map(|v|v as usize));assert_eq!(depths.last().copied(),fixture["maximumDepth"].as_u64().map(|v|v as usize));while let Some(expected)=reference.pop_first(){assert_eq!(index.pop_first(),Some(expected));}while !index.terminal_is_empty(){let p=index.close_copy_step_funded(items,index.next_close_copy_byte_demand(),index.next_close_release_byte_demand().unwrap()).unwrap();assert!(p.progressed);}}}
